/**
 * @file megaEvolution.js
 * Méga-évolution : mapping espèce → forme(s) méga (types officiels + stats POKEMON_BASE_STATS).
 * Charizard / Mewtwo / Raichu : variantes X / Y. Absol / Garchomp / Lucario : default (Gen 6) + Z.
 * Chargé après pokemonStats.js : fusionne les stats des formes "Mega …" dans POKEMON_BASE_STATS.
 */
import { POKEMON_BASE_STATS } from '../../pokemonStats.js';
import { TYPES } from '../core.ts';

const TP = TYPES;

/** Stats méga officielles (valeurs jeu /2 comme le reste du roster). */
function ms(hp: number, atk: number, def: number, spa: number, spd: number, spe: number) {
    return { hp, attack: atk / 2, spattack: spa / 2, defense: def / 2, spdefense: spd / 2, speed: spe / 2 };
}

