/**
 * @file src/ui/uiItems.ts
 * Typed accessors for item tables (ALL_ITEMS, HELD_ITEMS).
 */

import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';
import type { UiItemLike } from './uiTypes.ts';

const ALL_ITEMS_MAP = ALL_ITEMS as Record<string, UiItemLike & { type?: string }>;
const HELD_ITEMS_MAP = HELD_ITEMS as Record<string, UiItemLike>;

export function getAllItem(key: string): (UiItemLike & { type?: string }) | undefined {
    return ALL_ITEMS_MAP[key];
}

export function hasHeldItem(key: string): boolean {
    return key in HELD_ITEMS_MAP;
}

export function getHeldItem(key: string): UiItemLike | undefined {
    return HELD_ITEMS_MAP[key];
}
