export const MANUAL_MOVE_I18N_OVERRIDES = Object.freeze({
  "Gemme Lumiere": "Power Gem",
  "Poing de Feu": "Fire Punch",
  "Poing Meteor": "Meteor Mash",
});

export function localizeMoveName(name: string, lang?: string): string {
  const raw = String(name || "");
  if (!raw) return raw;
  const normalizedLang = (String(lang || "fr").toLowerCase().startsWith("en")) ? "en" : "fr";
  if (normalizedLang !== "en") return raw;
  const resolved = resolveMoveName(raw);
  const overrides = MANUAL_MOVE_I18N_OVERRIDES as Record<string, string>;
  const map = MOVE_NAME_I18N_EN as Record<string, string>;
  return overrides[resolved] || overrides[raw] || map[resolved] || map[raw] || raw;
}

const _global = globalThis as unknown as Record<string, unknown>;
_global.MOVE_NAME_I18N_EN = MOVE_NAME_I18N_EN;
_global.localizeMoveName = localizeMoveName;
