/**
 * Normalisation permissive des noms d'attaques pour gerer accents/ponctuation/legacy.
 */
export function _normalizeMoveLookupName(moveName: string | null | undefined): string {
    if (!moveName) return '';
    let text = String(moveName);
    // Corrige les rares chaines mojibake (UTF-8 lu en latin1)
    if (/[\u00c3\u0192\u00c2\u0085]/.test(text)) {
        try {
            text = decodeURIComponent(escape(text));
        } catch (_) {
            // keep original text if conversion fails
        }
    }
    return text
        .replace(/Å“/gi, 'oe')
        .replace(/æ/gi, 'ae')
        .replace(/\u00c3\u009f/g, 'ss')
        .replace(/['']/g, '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]/g, '')
        .toLowerCase();
}

export const MOVE_DB_NORMALIZED_NAME_INDEX: Record<string, string> = (() => {
    const index: Record<string, string> = {};
    Object.keys(MOVES_DB || {}).forEach(moveName => {
        const normalized = _normalizeMoveLookupName(moveName);
        if (!normalized) return;
        // First key wins to preserve historical in-file ordering.
        if (!index[normalized]) index[normalized] = moveName;
    });
    return index;
})();

export function resolveMoveName(moveName: string | null | undefined): string {
    if (!moveName) return 'Charge';
    if (MOVES_DB && (MOVES_DB as Record<string, unknown>)[moveName]) return moveName;
    const normalized = _normalizeMoveLookupName(moveName);
    if (!normalized) return 'Charge';
    return MOVE_DB_NORMALIZED_NAME_INDEX[normalized] || moveName;
}

export function hasMoveDefinition(moveName: string | null | undefined): boolean {
    if (!MOVES_DB) return false;
    const resolvedName = resolveMoveName(moveName);
    return !!(MOVES_DB as Record<string, unknown>)[resolvedName];
}

export function getMoveDefinition(moveName: string | null | undefined) {
    const resolvedName = resolveMoveName(moveName);
    const db = MOVES_DB as Record<string, Record<string, unknown>> | undefined;
    const base = (db && db[resolvedName]) ? db[resolvedName] : db ? db['Charge'] : null;
    if (!base) return null;
    const secondary = (MOVE_SECONDARY_EFFECTS as Record<string, import('../src/types/combat.ts').MoveSecondaryEffects>)[resolvedName];
    const meta = (MOVE_COMBAT_META as Record<string, import('../src/types/combat.ts').MoveCombatMeta>)[resolvedName];
    if (!secondary && !meta) return base;
    return { ...meta, ...secondary, ...base };
}

export function isDamagingMove(moveName: string | null | undefined): boolean {
    if (!MOVES_DB) return false;
    const resolvedName = resolveMoveName(moveName);
    const move = getMoveDefinition(resolvedName) as Record<string, unknown> | null;
    if (!move) return false;
    const retaliationMult = Number(move.retaliationMultiplier);
    if (Number.isFinite(retaliationMult) && retaliationMult > 0) return true;
    if (move.variableHpPowerMode === 'reversal' || move.variableHpPowerMode === 'flail') return true;
    const power = Number(move.power);
    return Number.isFinite(power) && power > 0;
}

/**
 * Retourne les PP de base d'une attaque.
 * Si MOVES_DB[moveName].pp est defini, on l'utilise.
 * Sinon on derive une valeur en fonction de la puissance.
 */
export function getMoveBasePP(moveName: string | null | undefined): number {
    const move = getMoveDefinition(moveName) as Record<string, unknown> | undefined;
    if (!move) return 20;
    if (typeof move.pp === 'number' && !isNaN(move.pp)) {
        return Math.max(1, Math.floor(move.pp));
    }
    const power = (typeof move.power === 'number' && Number.isFinite(move.power)) ? move.power : 50;
    if (power >= 130) return 5;
    if (power >= 100) return 10;
    if (power >= 70) return 15;
    return 20;
}

/**
 * Backward-compatible helper used by Creature.js.
 * Accepts a move definition object (or null) and returns a base PP estimate.
 */
export function getBasePPForMove(moveDef: Record<string, unknown> | null | undefined): number {
    if (!moveDef) return 10;
    if (typeof moveDef.pp === 'number' && !isNaN(moveDef.pp)) {
        return Math.max(1, Math.floor(moveDef.pp));
    }
    const power = typeof moveDef.power === 'number' ? moveDef.power : 50;
    if (power >= 130) return 5;
    if (power >= 110) return 8;
    if (power >= 90) return 10;
    if (power >= 70) return 15;
    if (power >= 50) return 20;
    return 30;
}

