/**
 * @file src/ui/utils.ts
 * Utilitaires UI : sprites, icones, rarity, etc.
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import { POKEMON_BASE_STATS } from '../../pokemonStats.ts';
import type { PokemonBaseStat } from '../../pokemonStats.ts';
import { getAllItem } from './uiItems.ts';
import type { UiItemLike } from './uiTypes.ts';

type PokemonSpriteStats = PokemonBaseStat & { sprite?: string; shinySprite?: string; image?: string };

export {
    GEN5_BW_SPRITE_BASE,
    GEN5_BW_ANIMATED_BASE,
    GEN5_SUBSTITUTE_SPRITE,
    getStaticFallbackFromAnimatedUrl,
    getPokemonSpriteUrl,
    capturePreviewSpriteUrl,
} from '../lib/cardSprites.ts';

import {
    GEN5_SUBSTITUTE_SPRITE,
    getPokemonSpriteUrl,
} from '../lib/cardSprites.ts';

const EGG_SPRITES: Record<string, string> = {
    common: 'img/common-egg.png',
    rare: 'img/rare-egg.png',
    epic: 'img/epic-egg.png',
    legendary: 'img/legendary-egg.png',
};

export function balanceRespawnUpgradeMsPerLevel(): number {
    return BALANCE.RESPAWN_UPGRADE_REDUCTION_PER_LEVEL ?? 50;
}

export function getItemIconPath(itemKey: string): string {
    const item = getAllItem(itemKey);
    if (item) {
        if (item.img) return item.img;
        if (item.image) return item.image;
        if (item.sprite) return item.sprite;
    }

    if (itemKey.startsWith('egg_')) {
        const rarity = itemKey.replace('egg_', '').toLowerCase();
        return EGG_SPRITES[rarity] ?? EGG_SPRITES.common ?? 'img/common-egg.png';
    }

    return 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/poke-ball.png';
}

export function getPokemonSpritePath(name: string, isShiny: boolean): string {
    const stats = POKEMON_BASE_STATS[name] as PokemonSpriteStats | undefined;
    if (stats) {
        if (isShiny && stats.shinySprite) return stats.shinySprite;
        if (!isShiny && stats.sprite) return stats.sprite;
        if (!isShiny && stats.image) return stats.image;
    }

    return getPokemonSpriteUrl(name, isShiny) || GEN5_SUBSTITUTE_SPRITE;
}

export function getTimeDustGlowClass(item: UiItemLike | null | undefined): string {
    if (!item?.effect || item.effect.type !== 'timeDust') return '';
    const hours = Math.max(0, Number(item.effect.hours) || 0);
    if (hours >= 6) return ' time-dust-glow-3';
    if (hours >= 3) return ' time-dust-glow-2';
    return '';
}

export function getItemIconHTML(item: UiItemLike | null | undefined): string {
    if (!item) return 'OBJ';
    if (item.img) {
        return `<img src="${item.img}" class="item-sprite-img${getTimeDustGlowClass(item)}" alt="${item.name ?? ''}">`;
    }
    return item.icon ?? 'OBJ';
}
